import { Title } from "@solidjs/meta";
import { action, useSubmission } from "@solidjs/router";
import { Show } from "solid-js";
import { validate, type ContactErrors, type ContactValues } from "~/lib/contact";

type Result = { values: ContactValues; errors: ContactErrors; ok: boolean };

function read(data: FormData | URLSearchParams): ContactValues {
  const g = (k: string) => (data.get(k) ?? "").toString().trim();
  return { name: g("name"), email: g("email"), message: g("message") };
}

async function send(values: ContactValues): Promise<Result> {
  "use server";
  const errors = validate(values);
  return { values, errors, ok: Object.keys(errors).length === 0 };
}

const sendMessage = action(async (data: FormData | URLSearchParams): Promise<Result> => {
  const values = read(data);
  const errors = validate(values);
  if (Object.keys(errors).length) return { values, errors, ok: false };
  return send(values);
}, "contact");

export default function Contact() {
  const sub = useSubmission(sendMessage);
  const res = () => sub.result as Result | undefined;
  const err = (k: keyof ContactValues) => res()?.errors[k];
  return (
    <>
      <Title>Contact | Bookshelf</Title>
      <h1>Contact</h1>
      <Show when={res()?.ok}>
        <p>Thanks, {res()!.values.name}! Your message has been sent.</p>
      </Show>
      <form action={sendMessage} method="post" novalidate>
        <label>
          Name
          <input type="text" name="name" value={res()?.values.name ?? ""} />
        </label>
        <Show when={err("name")}><span class="error">{err("name")}</span></Show>
        <label>
          Email
          <input type="email" name="email" value={res()?.values.email ?? ""} />
        </label>
        <Show when={err("email")}><span class="error">{err("email")}</span></Show>
        <label>
          Message
          <textarea name="message">{res()?.values.message ?? ""}</textarea>
        </label>
        <Show when={err("message")}><span class="error">{err("message")}</span></Show>
        <div><button type="submit">Send</button></div>
      </form>
    </>
  );
}
