import { createMiddleware } from "@solidjs/start/middleware";
import { getRequestEvent } from "solid-js/web";
import { handleContact } from "~/lib/contact-server";

export default createMiddleware([
  async (event, next) => {
    const url = new URL(event.req.url);
    if (event.req.method === "POST" && url.pathname === "/contact") {
      const result = handleContact(await event.req.formData());
      const re = getRequestEvent();
      if (re) re.locals.contact = result;
      (event as any).req = new Request(event.req.url, { method: "GET", headers: event.req.headers });
    }
    return next();
  }
]);
