import { Title } from "@solidjs/meta";
import { Show, createSignal } from "solid-js";
import { getRequestEvent, isServer } from "solid-js/web";
import { validate, type ContactValues } from "~/lib/contact";
import { handleContact, type Result } from "~/lib/contact-server";

async function send(data: FormData): Promise<Result> {
  "use server";
  return handleContact(data);
}

function initial(): Result | undefined {
  if (isServer) return getRequestEvent()?.locals.contact;
  const el = document.getElementById("contact-data");
  return el?.textContent ? JSON.parse(el.textContent) : undefined;
}

export default function Contact() {
  const [res, setRes] = createSignal<Result | undefined>(initial());
  const err = (k: keyof ContactValues) => res()?.errors[k];
  const onSubmit = async (e: SubmitEvent) => {
    e.preventDefault();
    const form = e.currentTarget as HTMLFormElement;
    const data = new FormData(form);
    const local = handleContact(data);
    if (!local.ok) return setRes(local);
    setRes(await send(data));
  };
  return (
    <>
      <Title>Contact | Bookshelf</Title>
      <h1>Contact</h1>
      <Show when={res()?.ok}>
        <p>Thanks, {res()!.values.name}! Your message has been sent.</p>
      </Show>
      <form action="/contact" method="post" novalidate onSubmit={onSubmit}>
        <label>
          Name
          <input type="text" name="name" value={res()?.values.name ?? ""} />
        </label>
        <Show when={err("name")}><span class="error">{err("name")}</span></Show>
        <label>
          Email
          <input type="email" name="email" value={res()?.values.email ?? ""} />
        </label>
        <Show when={err("email")}><span class="error">{err("email")}</span></Show>
        <label>
          Message
          <textarea name="message">{res()?.values.message ?? ""}</textarea>
        </label>
        <Show when={err("message")}><span class="error">{err("message")}</span></Show>
        <div><button type="submit">Send</button></div>
      </form>
      <Show when={isServer && res()}>
        <script type="application/json" id="contact-data" innerHTML={JSON.stringify(res()).replace(/</g, "\\u003c")} />
      </Show>
    </>
  );
}
EOF
